/**
 * Character-classification helpers that mirror the CPython predicates used by
 * `int()` and by `repr()`.
 *
 * Only the three questions the rest of the port actually asks are answered here:
 *   - is this character whitespace as far as `int()` is concerned?
 *   - what decimal value does this character carry?
 *   - is this character printable, i.e. may `repr()` emit it verbatim?
 */

/**
 * Code points for which CPython's `Py_UNICODE_ISSPACE` is true.
 *
 * This is deliberately an explicit table rather than a regex: the set includes
 * the C0 separators U+001C..U+001F, which no JavaScript character class covers,
 * and it excludes U+200B ZERO WIDTH SPACE, which some do.
 */
const SPACE_CODE_POINTS = new Set([
  0x09, 0x0a, 0x0b, 0x0c, 0x0d, // \t \n \v \f \r
  0x1c, 0x1d, 0x1e, 0x1f, // file/group/record/unit separators
  0x20, // space
  0x85, // next line
  0xa0, // no-break space
  0x1680, // ogham space mark
  0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
  0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
  0x2028, // line separator
  0x2029, // paragraph separator
  0x202f, // narrow no-break space
  0x205f, // medium mathematical space
  0x3000, // ideographic space
]);

/** Decimal-digit characters: Unicode general category Nd. */
const DECIMAL_DIGIT = /^\p{Nd}$/u;

/**
 * Categories `repr()` refuses to emit verbatim. Space is the documented
 * exception: it is Zs, yet CPython treats it as printable.
 */
const NON_PRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** True when `ch` is whitespace that `int()` strips. */
export function isSpace(ch) {
  return SPACE_CODE_POINTS.has(ch.codePointAt(0));
}

/**
 * Decimal value of `ch`, or -1 when it is not a decimal digit.
 *
 * Unicode lays decimal digits out as contiguous runs of ten starting at the
 * script's zero, so the value of a digit is its distance back to the first
 * character of its run. Walking backwards keeps every script working -- Arabic,
 * Devanagari, Thai, the mathematical alphanumerics -- without a lookup table.
 */
export function decimalValue(ch) {
  if (!DECIMAL_DIGIT.test(ch)) return -1;
  const cp = ch.codePointAt(0);
  for (let distance = 0; distance < 10; distance++) {
    const base = cp - distance;
    if (base === 0 || !DECIMAL_DIGIT.test(String.fromCodePoint(base - 1))) {
      return distance;
    }
  }
  return -1;
}

/** True when `repr()` may emit `ch` as itself rather than as an escape. */
export function isPrintable(ch) {
  return ch === ' ' || !NON_PRINTABLE.test(ch);
}

