/**
 * The handful of Python exception types this port needs to distinguish, plus
 * `SystemExit`, which argparse raises to unwind out of `parse_args`.
 */

/** Base class carrying the fully-qualified name CPython prints in tracebacks. */
export class PyError extends Error {
  constructor(message, qualifiedName) {
    super(message);
    this.name = qualifiedName;
  }
}

/** `ValueError` -- raised by `int()` on a malformed literal. */
export class PyValueError extends PyError {
  constructor(message) {
    super(message, 'ValueError');
  }
}

/**
 * `SystemExit`. Carries the status the interpreter should exit with; the entry
 * point catches it instead of terminating mid-parse.
 */
export class SystemExit extends PyError {
  constructor(status) {
    super(String(status), 'SystemExit');
    this.status = status;
  }
}

