/**
 * `repr()` for `bytes` and `str`.
 *
 * `print(some_bytes)` emits the repr, so this module is what actually produces
 * the program's output. Both functions share CPython's quote-selection rule:
 * single quotes by default, switching to double quotes when the value contains
 * an apostrophe but no double quote -- which is why the reference build prints
 * `b"'\\"` for bytes 39/92 but `b'"\''` for bytes 34/39.
 */

import { isPrintable } from './unicodedata.mjs';

const SINGLE = 0x27; // '
const DOUBLE = 0x22; // "
const BACKSLASH = 0x5c; // \

/** Pick the quote character, preferring `'` unless that would need escaping. */
function selectQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? "'" : "'";
}

function twoDigitHex(code) {
  return code.toString(16).padStart(2, '0');
}

/**
 * `repr(bytes(values))`.
 *
 * @param {Iterable<number>} values byte values in 0..255
 * @returns {string} e.g. `b'\x10\xa1'`
 */
export function reprBytes(values) {
  const bytes = Array.from(values);
  const hasSingle = bytes.includes(SINGLE);
  const hasDouble = bytes.includes(DOUBLE);
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const byte of bytes) {
    if (byte === BACKSLASH) out += '\\\\';
    else if (byte === quoteCode) out += '\\' + quote;
    else if (byte === 0x09) out += '\\t';
    else if (byte === 0x0a) out += '\\n';
    else if (byte === 0x0d) out += '\\r';
    // Only tab, newline and carriage return get letter escapes; backspace,
    // vertical tab and form feed fall through to \xNN.
    else if (byte >= 0x20 && byte < 0x7f) out += String.fromCharCode(byte);
    else out += '\\x' + twoDigitHex(byte);
  }
  return out + quote;
}

/**
 * `repr(str)`.
 *
 * Printable non-ASCII characters are emitted as themselves; unprintable ones
 * become `\xNN`, `\uNNNN` or `\UNNNNNNNN` by code-point width.
 */
export function reprStr(text) {
  const hasSingle = text.includes("'");
  const hasDouble = text.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\t') out += '\\t';
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (isPrintable(ch)) out += ch;
    else if (cp < 0x100) out += '\\x' + twoDigitHex(cp);
    else if (cp < 0x10000) out += '\\u' + cp.toString(16).padStart(4, '0');
    else out += '\\U' + cp.toString(16).padStart(8, '0');
  }
  return out + quote;
}

