/**
 * An immutable `bytes` value.
 *
 * Byte values live in a plain array of numbers -- that is all a byte string is,
 * and it keeps the type printable and comparable without any binary-buffer
 * machinery.
 */

import { reprBytes } from './repr.mjs';

export class PyBytes {
  /** @param {Iterable<number>} values byte values in 0..255 */
  constructor(values = []) {
    this._values = Object.freeze(Array.from(values));
  }

  /** Concatenate byte strings, as `b'a' + b'b'` does. */
  static concat(chunks) {
    const values = [];
    for (const chunk of chunks) {
      values.push(...(chunk instanceof PyBytes ? chunk.values : chunk));
    }
    return new PyBytes(values);
  }

  /** The underlying byte values (frozen). */
  get values() {
    return this._values;
  }

  /** `len(b)` */
  get length() {
    return this._values.length;
  }

  /** `repr(b)` */
  repr() {
    return reprBytes(this._values);
  }

  /**
   * `str(b)`, which for `bytes` is the same as `repr(b)` -- the reason
   * `print(data)` shows `b'\x10\xa1'` rather than raw bytes.
   */
  toString() {
    return this.repr();
  }
}

