/**
 * Usage and help text generation.
 *
 * Reproduces argparse's `HelpFormatter` layout for flag-only parsers: the usage
 * line, then an `options:` section whose help column sits at
 * `min(widest_invocation + indent + 2, 24)`.
 */

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** `--a` -> `A`: the default metavar is the dest upper-cased. */
export function defaultMetavar(dest) {
  return dest.toUpperCase();
}

/** How an action appears in the usage line, e.g. `[-h]` or `--a A`. */
function usageFragment(action) {
  const optionString = action.optionStrings[0];
  const body = action.takesValue
    ? `${optionString} ${action.metavar}`
    : optionString;
  return action.required ? body : `[${body}]`;
}

/** How an action appears in the options section, e.g. `-h, --help`. */
function invocation(action) {
  if (!action.takesValue) return action.optionStrings.join(', ');
  return action.optionStrings.map((s) => `${s} ${action.metavar}`).join(', ');
}

/** `usage: prog [-h] --a A --b B` (no trailing newline). */
export function formatUsage(prog, actions) {
  const parts = actions.map(usageFragment);
  return `usage: ${[prog, ...parts].join(' ')}`;
}

/** The full `--help` body, ending in exactly one newline. */
export function formatHelp(prog, actions) {
  const invocations = actions.map(invocation);
  const widest = Math.max(0, ...invocations.map((s) => s.length + INDENT));
  const helpColumn = Math.min(widest + 2, MAX_HELP_POSITION);

  const lines = [formatUsage(prog, actions), '', 'options:'];
  actions.forEach((action, index) => {
    const label = ' '.repeat(INDENT) + invocations[index];
    if (!action.help) {
      lines.push(label);
      return;
    }
    if (label.length < helpColumn) {
      lines.push(label + ' '.repeat(helpColumn - label.length) + action.help);
    } else {
      // Too wide to share the line: help drops to its own line, as argparse does.
      lines.push(label, ' '.repeat(helpColumn) + action.help);
    }
  });
  return lines.join('\n') + '\n';
}

