/**
 * A subset of `argparse.ArgumentParser` covering optional flags with `type` and
 * `required`, plus the automatic `-h/--help`.
 *
 * The behaviours reproduced here were each checked against the reference build:
 *   - `--a 16` and `--a=16` are equivalent
 *   - unique long-option prefixes are accepted (`--he` means `--help`)
 *   - `-1` and `-` are values, `-x` is an unknown option
 *   - a repeated option keeps the last value
 *   - `--` ends option parsing
 *   - errors go to stderr with status 2; `--help` goes to stdout with status 0
 *   - required options are reported before unrecognised ones
 */

import { SystemExit } from '../python/errors.mjs';
import { ArgumentError } from './errors.mjs';
import { defaultMetavar, formatHelp, formatUsage } from './formatter.mjs';

/** `^-\d+$|^-\d*\.\d+$` -- argparse's test for a value that merely looks like a flag. */
const NEGATIVE_NUMBER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog ?? 'prog';
    this.actions = [];
    this._byOptionString = new Map();
    this.addArgument(['-h', '--help'], {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * Register an optional argument.
   *
   * @param {string|string[]} names option strings, e.g. `'--a'`
   * @param {{action?: string, type?: {name: string, convert: Function},
   *          required?: boolean, help?: string, metavar?: string}} options
   */
  addArgument(names, options = {}) {
    const optionStrings = Array.isArray(names) ? names : [names];
    const longest = optionStrings.find((s) => s.startsWith('--')) ?? optionStrings[0];
    const dest = longest.replace(/^-+/, '').replace(/-/g, '_');
    const action = {
      optionStrings,
      dest,
      isHelp: options.action === 'help',
      takesValue: options.action !== 'help',
      type: options.type ?? null,
      required: options.required ?? false,
      help: options.help ?? '',
      metavar: options.metavar ?? defaultMetavar(dest),
    };
    this.actions.push(action);
    for (const optionString of optionStrings) {
      this._byOptionString.set(optionString, action);
    }
    return action;
  }

  /** `'/'.join(action.option_strings)`, the name argparse puts in error text. */
  _actionName(action) {
    return action.optionStrings.join('/');
  }

  /** Long options that `prefix` unambiguously abbreviates. */
  _prefixMatches(prefix) {
    if (!prefix.startsWith('--')) return [];
    return [...this._byOptionString.keys()].filter(
      (optionString) => optionString.startsWith('--') && optionString.startsWith(prefix),
    );
  }

  /**
   * Classify a token as an option (`'O'`) or a value (`'A'`), following
   * argparse's `_parse_optional`.
   */
  _classify(token) {
    if (token === '') return 'A';
    if (!token.startsWith('-')) return 'A';
    if (this._byOptionString.has(token)) return 'O';
    if (token.length === 1) return 'A'; // a bare '-' is a value
    if (token.includes('=')) {
      const name = token.slice(0, token.indexOf('='));
      if (this._byOptionString.has(name)) return 'O';
    }
    if (this._prefixMatches(token).length > 0) return 'O';
    // No option string looks like a negative number, so numbers are values.
    if (NEGATIVE_NUMBER.test(token)) return 'A';
    if (token.includes(' ')) return 'A';
    return 'O';
  }

  /** Resolve an option string to its action, or null when unknown. */
  _resolve(optionString) {
    const exact = this._byOptionString.get(optionString);
    if (exact) return exact;
    const matches = this._prefixMatches(optionString);
    if (matches.length === 1) return this._byOptionString.get(matches[0]);
    if (matches.length > 1) {
      throw new ArgumentError(
        null,
        `ambiguous option: ${optionString} could match ${matches.join(', ')}`,
      );
    }
    return null;
  }

  /** Apply `type` to a raw string, translating ValueError into argparse's wording. */
  _convert(action, raw) {
    if (!action.type) return raw;
    try {
      return action.type.convert(raw);
    } catch {
      throw new ArgumentError(
        this._actionName(action),
        `invalid ${action.type.name} value: ${reprOf(raw)}`,
      );
    }
  }

  /**
   * Parse `argv`, or `process.argv.slice(2)` when omitted.
   *
   * @returns {object} the namespace, keyed by dest
   * @throws {SystemExit} on `--help` (status 0) or any parse error (status 2)
   */
  parseArgs(argv = process.argv.slice(2)) {
    try {
      return this._parse(argv);
    } catch (error) {
      if (error instanceof ArgumentError) this.error(error.message);
      throw error;
    }
  }

  _parse(argv) {
    const namespace = {};
    const provided = new Set();
    const extras = [];
    let valuesOnly = false;

    for (let index = 0; index < argv.length; index++) {
      const token = argv[index];
      if (valuesOnly) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        valuesOnly = true;
        continue;
      }
      if (this._classify(token) === 'A') {
        extras.push(token);
        continue;
      }

      let optionString = token;
      let explicitValue = null;
      const equals = token.indexOf('=');
      if (equals >= 0) {
        optionString = token.slice(0, equals);
        explicitValue = token.slice(equals + 1);
      }

      const action = this._resolve(optionString);
      if (!action) {
        extras.push(token);
        continue;
      }

      if (action.isHelp) {
        this.printHelp();
        throw new SystemExit(0);
      }

      let raw = explicitValue;
      if (raw === null) {
        const next = argv[index + 1];
        if (next === undefined || this._classify(next) === 'O') {
          throw new ArgumentError(this._actionName(action), 'expected one argument');
        }
        raw = next;
        index++;
      }
      namespace[action.dest] = this._convert(action, raw);
      provided.add(action);
    }

    // Missing required options are reported before unrecognised tokens, matching
    // argparse's split between parse_known_args and parse_args.
    const missing = this.actions
      .filter((action) => action.required && !provided.has(action))
      .map((action) => this._actionName(action));
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    for (const action of this.actions) {
      if (action.takesValue && !(action.dest in namespace)) {
        namespace[action.dest] = null; // argparse's default of None
      }
    }
    return namespace;
  }

  formatUsage() {
    return formatUsage(this.prog, this.actions);
  }

  formatHelp() {
    return formatHelp(this.prog, this.actions);
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  /** Report a usage error on stderr and exit with status 2. */
  error(message) {
    process.stderr.write(`${this.formatUsage()}\n`);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }
}

