/**
 * `FormatField` -- construct's fixed-width integer fields.
 *
 * Packing is plain BigInt arithmetic over an array of byte values: shift, mask,
 * append. Two's complement for the signed widths is a single addition of the
 * modulus, and byte order is just the direction the array is filled.
 */

import { FormatFieldError, StructError } from './errors.mjs';

/**
 * The `struct` format characters, with their width and signedness.
 * Keyed exactly as `struct` spells them so `fmtstr` round-trips into messages.
 */
const FORMATS = new Map([
  ['b', { size: 1, signed: true }],
  ['B', { size: 1, signed: false }],
  ['h', { size: 2, signed: true }],
  ['H', { size: 2, signed: false }],
  ['i', { size: 4, signed: true }],
  ['I', { size: 4, signed: false }],
  ['l', { size: 4, signed: true }],
  ['L', { size: 4, signed: false }],
  ['q', { size: 8, signed: true }],
  ['Q', { size: 8, signed: false }],
]);

/** Inclusive range a format character accepts. */
function limitsOf({ size, signed }) {
  const bits = BigInt(size) * 8n;
  return signed
    ? { low: -(2n ** (bits - 1n)), high: 2n ** (bits - 1n) - 1n }
    : { low: 0n, high: 2n ** bits - 1n };
}

export class FormatField {
  /**
   * @param {'<'|'>'} endianity `<` little-endian, `>` big-endian
   * @param {string} format a `struct` format character, e.g. `'B'`
   */
  constructor(endianity, format) {
    const spec = FORMATS.get(format);
    if (!spec) throw new Error(`unsupported format character: ${format}`);
    this.endianity = endianity;
