/**
 * `Struct` and the field-naming helper.
 *
 * Python spells naming with a division operator -- `"field1" / Int8ul` -- which
 * builds a `Renamed` subconstruct. JavaScript cannot overload `/`, so `named()`
 * takes its place; `Struct` also accepts `['field1', Int8ul]` pairs.
 */

import { PyBytes } from '../python/bytes.mjs';
import { ConstructError } from './errors.mjs';

/** `"name" / subcon` -- a copy of `subcon` carrying a field name. */
export function named(name, subcon) {
  const renamed = Object.create(Object.getPrototypeOf(subcon));
  Object.assign(renamed, subcon);
  renamed.name = name;
  return renamed;
}

/** Accept either `named(...)` output or a `[name, subcon]` pair. */
function toSubcon(entry) {
  return Array.isArray(entry) ? named(entry[0], entry[1]) : entry;
}

class StructConstruct {
  constructor(subcons) {
    this.subcons = subcons;
  }

  /**
   * `struct.build(obj)` -- serialise `obj` to bytes.
   *
   * @param {object} obj values keyed by field name
   * @returns {PyBytes}
   */
  build(obj) {
    return this.buildStream(obj, '(building)');
  }

  /** The path-seeded inner build; `build` supplies construct's root path. */
  buildStream(obj, path) {
    return new PyBytes(this._build(obj, obj, path));
  }

  _build(obj, context, path) {
    const chunks = [];
    for (const subcon of this.subcons) {
      // Each field extends the path, giving errors their `-> field1` suffix.
      const subPath = subcon.name === null ? path : `${path} -> ${subcon.name}`;
      const value = subcon.name === null ? obj : obj[subcon.name];
      chunks.push(...subcon._build(value, context, subPath));
    }
    return chunks;
  }
}

/**
 * `construct.Struct(...)` -- a sequence of named fields built in order.
 *
 * @param {...(object|[string, object])} entries fields, from `named()` or pairs
 */
export function Struct(...entries) {
  return new StructConstruct(entries.map(toSubcon));
}

export { StructConstruct, ConstructError };

