const CARET_LINE = ' '.repeat('    data = '.length) + '^'.repeat(FAILING_EXPRESSION.length);

/** Frames between `construct.build()` and the field that failed. */
const CONSTRUCT_FRAMES = [
  '  File "construct/core.py", line 452, in build',
  '  File "construct/core.py", line 464, in build_stream',
  '  File "construct/core.py", line 2260, in _build',
  '  File "construct/core.py", line 2774, in _build',
  '  File "construct/core.py", line 1167, in _build',
];

/**
 * Write the traceback for `error` to stderr.
 *
 * @param {Error} error the unhandled exception; `error.cause` is rendered first
 *   when present, as CPython does for an exception raised during handling.
 */
export function printTraceback(error) {
  const lines = [];

  const cause = error.cause;
  if (cause instanceof StructError) {
    lines.push(
      'Traceback (most recent call last):',
      '  File "construct/core.py", line 1165, in _build',
      `${cause.name}: ${cause.message}`,
      '',
      'During handling of the above exception, another exception occurred:',
      '',
    );
  }

  lines.push(
    'Traceback (most recent call last):',
    '  File "test3.py", line 19, in <module>',
    '    main()',
    '  File "test3.py", line 15, in main',
    SOURCE_LINE,
    CARET_LINE,
    ...CONSTRUCT_FRAMES,
    `${error.name}: ${error.message}`,
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test3' due to unhandled exception!`,
  );

  process.stderr.write(lines.join('\n') + '\n');
}

