 * packaged as `test3_executable`, so its usage and error lines are pinned to
 * that name to keep this port's output byte-identical.
 */
const PROG = 'test3_executable';

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--a', { type: intType, required: true });
  parser.addArgument('--b', { type: intType, required: true });
  const args = parser.parseArgs();

  const structFormat = construct.Struct(
    construct.named('field1', construct.Int8ul), // 定义第一个字段
    construct.named('field2', construct.Int8ul), // 定义第二个字段
  );
  const data = structFormat.build({ field1: args.a, field2: args.b }); // 构建结构体
  pyPrint(data);
}

try {
  main();
