  if (error instanceof SystemExit) {
    process.exitCode = error.status;
  } else if (error instanceof ConstructError) {
    // An out-of-range value reaches the packer: the reference program lets the
    // exception escape, printing a traceback and exiting 1.
    printTraceback(error);
    process.exitCode = 1;
  } else {
    throw error;
  }
