toolUseResult.originalFile:
/**
 * `int(str)` with base 10, as CPython implements it.
 *
 * The accepted grammar, confirmed against the reference build:
 *
 *     int  := space* sign? group ('_' group)* space*
 *     sign := '+' | '-'
 *     group := digit+
 *
 * so `'  16 '`, `'+16'`, `'0016'`, `'1_6'` and `'١٦'` all parse, while `'_16'`,
 * `'16_'`, `'1__6'`, `'0x10'`, `'16.5'` and `''` all raise ValueError.
 *
 * Results are BigInt: Python integers are unbounded, and an out-of-range value
 * is echoed back verbatim in the struct-packing error message, so a 30-digit
 * argument has to survive the round trip without losing precision.
 */

import { PyValueError } from './errors.mjs';
import { decimalValue, isSpace } from './unicodedata.mjs';
import { reprStr } from './repr.mjs';

/** Strip the leading and trailing run of `int()`-recognised whitespace. */
function stripSpace(text) {
  let start = 0;
  let end = text.length;
  while (start < end && isSpace(text[start])) start++;
  while (end > start && isSpace(text[end - 1])) end--;
  return text.slice(start, end);
}

/**
 * Convert `text` to a BigInt.
 *
 * @throws {PyValueError} with CPython's exact message when `text` is malformed.
 */
export function pyInt(text) {
  const body = stripSpace(text);
  let index = 0;

  let negative = false;
  if (body[index] === '+' || body[index] === '-') {
    negative = body[index] === '-';
    index++;
  }

  // Digits are accumulated as a decimal string so that scripts other than ASCII
  // can be folded into a form BigInt understands.
  let digits = '';
  let digitsInGroup = 0;
  for (; index < body.length; index++) {
    const ch = body[index];
    if (ch === '_') {
      // An underscore must sit between two digits: never leading, trailing or
      // doubled.
      if (digitsInGroup === 0) throw invalidLiteral(text);
      digitsInGroup = 0;
      continue;
    }
    const value = decimalValue(ch);
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    digitsInGroup++;
  }
  if (digitsInGroup === 0) throw invalidLiteral(text);

  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}

function invalidLiteral(text) {
  return new PyValueError(
    `invalid literal for int() with base 10: ${reprStr(text)}`,
  );
}

/**
 * The callable argparse receives as `type=int`. Bundling the display name with
 * the conversion mirrors argparse reading `type.__name__` for its error text.
 */
export const intType = { name: 'int', convert: pyInt };
